from werkzeug.utils import secure_filename
def store_evidence(case_id, file_obj):
    if not case_id.replace('-', '').isalnum():
        raise ValueError('Invalid case')
    fn = secure_filename(file_obj.filename)
    if not fn:
        raise ValueError('Invalid file')
    dest_dir = os.path.realpath(os.path.join('/srv/evidence', case_id))
    os.makedirs(dest_dir, exist_ok=True)
    full = os.path.realpath(os.path.join(dest_dir, fn))
    if not full.startswith(dest_dir + os.sep):
        raise ValueError('denied')
    file_obj.save(full)
    return fn

