class FileServer:
    BASE = '/public'
    def serve(self, filename):
        from pathlib import Path
        safe = Path(self.BASE) / Path(filename).name
        if not str(safe.resolve()).startswith(self.BASE):
            raise ValueError('Access denied')
        return safe.read_bytes()

